from itertools import combinations
import random

def check_graph(edges, n=11):
    """Check if a graph satisfies all constraints."""
    # Build adjacency list
    adj = [[] for _ in range(n)]
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)

    # Check min degree >= 3
    for i in range(n):
        if len(adj[i]) < 3:
            return False, "min degree < 3"

    # Check max degree <= 5
    for i in range(n):
        if len(adj[i]) > 5:
            return False, "max degree > 5"

    # Check edges between 7 and 19
    if len(edges) < 7 or len(edges) > 19:
        return False, f"edges = {len(edges)} not in [7, 19]"

    # Check chromatic number
    chi = chromatic_number(adj, n)
    if chi < 3 or chi > 4:
        return False, f"chromatic number = {chi}"

    return True, f"Valid! edges={len(edges)}, chi={chi}"

def chromatic_number(adj, n):
    """Compute chromatic number using backtracking."""
    def can_color(coloring, vertex, color):
        for neighbor in adj[vertex]:
            if neighbor < vertex and coloring[neighbor] == color:
                return False
        return True

    def backtrack(vertex, coloring, max_colors):
        if vertex == n:
            return True
        for color in range(max_colors):
            if can_color(coloring, vertex, color):
                coloring[vertex] = color
                if backtrack(vertex + 1, coloring, max_colors):
                    return True
                coloring[vertex] = -1
        return False

    for k in range(1, n + 1):
        coloring = [-1] * n
        if backtrack(0, coloring, k):
            return k
    return n

